import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"5.1 低压电器概述与分类","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-1-di-ya-dian-qi-gai-shu-yu-fen-lei.md","filePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-1-di-ya-dian-qi-gai-shu-yu-fen-lei.md","lastUpdated":1793095197000}'),e={name:"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-1-di-ya-dian-qi-gai-shu-yu-fen-lei.md"};function o(n,t,d,s,h,u){return i(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="_5-1-低压电器概述与分类" tabindex="-1">5.1 低压电器概述与分类 <a class="header-anchor" href="#_5-1-低压电器概述与分类" aria-label="Permalink to &quot;5.1 低压电器概述与分类&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>低压电器是电气控制系统的&quot;零部件&quot;。这一节先建立整体框架:低压电器是什么、分几类、有哪些基本要求。后面 5.2~5.8 逐个认识每一种电器,每个都要回答三个问题:<strong>管什么、怎么动作、怎么选</strong>。</p><h2 id="一、什么是低压电器" tabindex="-1">一、什么是低压电器 <a class="header-anchor" href="#一、什么是低压电器" aria-label="Permalink to &quot;一、什么是低压电器&quot;">​</a></h2><p><strong>低压电器</strong>,指用于 <strong>1 kV 以下(交流 1200 V、直流 1500 V 及以下)<strong>电路中的电器元件。它们负责电路的</strong>通断、控制、保护、调节</strong>。</p><h2 id="二、低压电器的分类" tabindex="-1">二、低压电器的分类 <a class="header-anchor" href="#二、低压电器的分类" aria-label="Permalink to &quot;二、低压电器的分类&quot;">​</a></h2><h3 id="_1-按用途分-最常用分类" tabindex="-1">1. 按用途分(最常用分类) <a class="header-anchor" href="#_1-按用途分-最常用分类" aria-label="Permalink to &quot;1. 按用途分(最常用分类)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>作用</th><th>典型电器</th></tr></thead><tbody><tr><td><strong>配电电器</strong></td><td>用于供配电电路的接通、断开和保护</td><td>刀开关、熔断器、低压断路器、漏电保护器</td></tr><tr><td><strong>控制电器</strong></td><td>用于控制电动机等用电设备的启停、转向</td><td>接触器、继电器、主令电器(按钮、行程开关)</td></tr></tbody></table><h3 id="_2-按动作方式分" tabindex="-1">2. 按动作方式分 <a class="header-anchor" href="#_2-按动作方式分" aria-label="Permalink to &quot;2. 按动作方式分&quot;">​</a></h3><ul><li><strong>手动电器</strong>:靠人工操作,如刀开关、按钮;</li><li><strong>自动电器</strong>:靠电磁、热、机械作用自动动作,如接触器、热继电器、时间继电器。</li></ul><h3 id="_3-按工作条件分" tabindex="-1">3. 按工作条件分 <a class="header-anchor" href="#_3-按工作条件分" aria-label="Permalink to &quot;3. 按工作条件分&quot;">​</a></h3><ul><li><strong>一般工业用电器</strong>;</li><li>特殊场合(湿热、化工、防爆)用电器。</li></ul><h2 id="三、低压电器的基本要求" tabindex="-1">三、低压电器的基本要求 <a class="header-anchor" href="#三、低压电器的基本要求" aria-label="Permalink to &quot;三、低压电器的基本要求&quot;">​</a></h2><ol><li><strong>动作可靠</strong>:该通就通、该断就断,不能误动作;</li><li><strong>分断能力足够</strong>:能可靠切断短路电流、过载电流;</li><li><strong>绝缘可靠</strong>:电气绝缘满足安全要求;</li><li><strong>使用寿命长</strong>:机械寿命、电气寿命满足要求;</li><li><strong>灭弧性能好</strong>:分断时电弧能迅速熄灭。</li></ol><blockquote><p>⚠️ 低压电器分断电路时会产生<strong>电弧</strong>,电弧会烧蚀触头甚至引燃设备,所以灭弧能力很重要(断路器、接触器都有灭弧装置)。</p></blockquote><h2 id="四、电气系统里-谁负责什么-预习" tabindex="-1">四、电气系统里&quot;谁负责什么&quot;(预习) <a class="header-anchor" href="#四、电气系统里-谁负责什么-预习" aria-label="Permalink to &quot;四、电气系统里&quot;谁负责什么&quot;(预习)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>保护对象</th><th>负责的电器</th></tr></thead><tbody><tr><td>短路保护</td><td>熔断器、低压断路器</td></tr><tr><td>过载保护</td><td>热继电器、低压断路器</td></tr><tr><td>漏电(人身)保护</td><td>漏电保护器</td></tr><tr><td>远距离启停控制</td><td>接触器 + 按钮</td></tr><tr><td>顺序/延时控制</td><td>时间继电器</td></tr></tbody></table><blockquote><p>💡 这一行表格是全书&quot;低压电器&quot;部分的地图,学完 5.2~5.8 后再回来对照,印象更深。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 低压电器 = 1 kV 以下电路中的电器。</li><li>✅ 配电电器(刀开关、熔断器、断路器、漏保)vs 控制电器(接触器、继电器、按钮)。</li><li>✅ 短路保护靠熔断器/断路器,过载保护靠热继电器/断路器,漏电保护靠漏保。</li><li>⚠️ 易混点:每种保护对应的电器别串线——这是判断题常考方向。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>低压电器分配电电器和控制电器两大类。</li><li>基本要求:动作可靠、分断力强、绝缘好、寿命长、灭弧好。</li><li>建立&quot;短路/过载/漏电各自找谁&quot;的保护地图。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)低压电器是用于 1 kV 以下电路中的电器元件。( )</li><li>(单选)下列属于控制电器的是()。 A. 熔断器　B. 交流接触器　C. 刀开关　D. 低压断路器</li><li>(判断)熔断器、低压断路器属于配电电器。( )</li><li>(单选)电动机的过载保护一般由()承担。 A. 熔断器　B. 热继电器　C. 漏电保护器　D. 刀开关</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。低压电器用于 1 kV 以下电路。</li><li><strong>B</strong>。接触器、继电器、按钮是控制电器。</li><li><strong>√</strong>。刀开关、熔断器、断路器、漏保是配电电器。</li><li><strong>B</strong>。过载保护用热继电器,短路保护用熔断器。</li></ol></details>',25)])])}const q=a(e,[["render",o]]);export{g as __pageData,q as default};
